#!/usr/bin/env bash
# =============================================================================
# apply-dependency-patches.sh — STAGE B (deferred patch application)
#
# Applies the dependency patches generated by generate-dependency-patches.sh for
# ONE component to that component's source checkout. It is called by the
# opensearch-build hook (BuilderFromSource.checkout) for the component being
# prepared, after its checkout and before its ./gradlew runs, so Gradle reads the
# patched gradle/libs.versions.toml.
#
# Usage:
#   apply-dependency-patches.sh --patches-dir <dir> --component <name> --repo-dir <checkout>
#
#   --component  Manifest component name; patches are read from <patches-dir>/<name>/*.patch
#                in file-name order. No such directory/patches => nothing selected for it,
#                the checkout is left unchanged.
#
# Guarantees: patches are checked before applying; any failure exits non-zero; a patch
# already applied to this checkout (tracked in <git-dir>/ppc-dependency-patches.applied)
# is skipped, never applied twice.
# =============================================================================
set -euo pipefail

info()    { echo "[INFO] $*"; }
success() { echo "[SUCCESS] $*"; }
skip()    { echo "[SKIP] $*"; }
fail()    { echo "[ERROR] $*" >&2; exit 1; }
usage()   { sed -n '/^# Usage:/,/^# Guarantees/p' "$0" | sed '$d; s/^# \{0,1\}//' >&2; exit 1; }

PATCHES_DIR=""; COMPONENT=""; REPO_DIR=""
while [[ $# -gt 0 ]]; do
    case "$1" in
        --patches-dir) [[ $# -ge 2 ]] || usage; PATCHES_DIR="$2"; shift 2 ;;
        --component)   [[ $# -ge 2 ]] || usage; COMPONENT="$2";   shift 2 ;;
        --repo-dir)    [[ $# -ge 2 ]] || usage; REPO_DIR="$2";    shift 2 ;;
        -h|--help)     usage ;;
        *)             echo "[ERROR] Unknown option: $1" >&2; usage ;;
    esac
done
[[ -n "${PATCHES_DIR}" && -n "${COMPONENT}" && -n "${REPO_DIR}" ]] \
    || { echo "[ERROR] --patches-dir, --component and --repo-dir are required" >&2; usage; }
[[ -d "${PATCHES_DIR}" ]] || fail "Patches directory not found: ${PATCHES_DIR}"
PATCHES_DIR="$(cd "${PATCHES_DIR}" && pwd)"   # absolute: git -C changes the working directory
[[ "${COMPONENT}" =~ ^[A-Za-z0-9._-]+$ ]] || fail "Invalid component name: ${COMPONENT}"

COMPONENT_PATCHES=()
if [[ -d "${PATCHES_DIR}/${COMPONENT}" ]]; then
    while IFS= read -r f; do COMPONENT_PATCHES+=("${f}"); done \
        < <(find "${PATCHES_DIR}/${COMPONENT}" -maxdepth 1 -type f -name '*.patch' | sort)
fi
if [[ ${#COMPONENT_PATCHES[@]} -eq 0 ]]; then
    skip "${COMPONENT}: no dependency patch selected; checkout left unchanged."
    exit 0
fi

[[ -d "${REPO_DIR}" ]] || fail "${COMPONENT} checkout directory not found: ${REPO_DIR}"
GIT_DIR="$(git -C "${REPO_DIR}" rev-parse --absolute-git-dir 2>/dev/null)" \
    || fail "${REPO_DIR} is not a git checkout"
MARKER="${GIT_DIR}/ppc-dependency-patches.applied"
touch "${MARKER}"

info "Applying dependency patches to ${COMPONENT} (${REPO_DIR})."
for patch in "${COMPONENT_PATCHES[@]}"; do
    [[ -s "${patch}" ]] || fail "Patch is empty: ${patch}"
    id="$(git hash-object "${patch}")"
    name="$(basename "${patch}")"
    if grep -qx "${id}" "${MARKER}"; then
        skip "${COMPONENT}: ${name} already applied to this checkout."
        continue
    fi
    git -C "${REPO_DIR}" apply --check --whitespace=nowarn "${patch}" \
        || fail "${COMPONENT}: ${name} does not apply cleanly to ${REPO_DIR}"
    git -C "${REPO_DIR}" apply --whitespace=nowarn "${patch}" \
        || fail "${COMPONENT}: failed to apply ${name}"
    echo "${id}" >> "${MARKER}"
    success "${COMPONENT}: ${name} applied."
done
success "Dependency patches applied to ${COMPONENT}."
